('138c8342-8ff5-4475-b245-d95a742e3ddf','MA','a0a0a0a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Desert Nomad Tours SARL','Desert Nomad Tours','desert_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'A Berber family business running camel treks and overnight camps in the dunes since 2005. Basic but authentic — real nomad-style camps with woven tents and campfire music.',6.2,89.2,279,4.6,'active'),
('398f8b47-6e15-4ac3-b1ce-340b6f5fcee6','MA','a0a0a0a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Erg Luxury Expeditions SARL','Erg Luxury Expeditions','desert_experience',4,'verified',ARRAY['en','fr','es','it'],'Premium desert experiences with luxury glamping tents (real beds, en-suite bathrooms), gourmet dinners, and 4x4 Land Cruisers. Stargazing with a telescope included.',10.4,91.1,390,4.6,'active'),
('9c27c727-06a9-4c30-a037-b7ae6a2266d1','MA','a0a0a0a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dune Riders Tinghir SARL','Dune Riders Tinghir','desert_experience',2,'verified',ARRAY['en','fr'],'A young team of desert enthusiasts offering sandboarding, quad biking, and buggy tours. Half-day and full-day options. Includes picnic lunch and water.',3.5,89.6,435,3.7,'active'),
('e6cc9f31-b938-4a56-8c29-cd31e27d5c16','MA','a0a0a0a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Tinghir Shuttle Express SARL','Tinghir Shuttle Express','transfer',1,'verified',ARRAY['en','fr'],'Affordable shared shuttle service between the airport, train stations, and city hotels. Fixed schedules, comfortable minibuses, and friendly drivers.',6.7,95.9,155,3.7,'active'),
('68a7804b-91b0-44f8-92cb-e7b606b73ce6','MA','a0a0a0a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Private Transfers SARL','Atlas Private Transfers','transfer',3,'verified',ARRAY['en','fr','ar'],'Private door-to-door transfers with professional drivers and modern sedan cars. Flight tracking, meet-and-greet at the airport, and 24/7 availability.',9.6,97.8,114,4.6,'active'),
('ed31d547-0fbc-42d0-944a-5720d2b4aa2d','MA','a0a0a0a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Chauffeur Morocco SARL','Royal Chauffeur Morocco','transfer',4,'verified',ARRAY['en','fr','es'],'Luxury chauffeur service with Mercedes E-Class and V-Class vehicles. Leather interiors, bottled water, phone chargers, and English-speaking drivers in suits.',9.7,94.1,370,4.6,'active'),
('ef1d9457-4162-44f9-82ae-35b765193e29','MA','a07070a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dades Valley Heritage Walks SARL','Dades Valley Heritage Walks','tour',2,'verified',ARRAY['en','fr','ary-Latn'],'A family-run walking tour company founded in 2009. We specialize in intimate small-group tours of historic quarters, led by licensed local guides who grew up in these streets.',3.4,97.6,221,4.1,'active'),
('5ccba066-9300-40e9-9957-a5babf1abd2a','MA','a07070a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Cultural Tours SARL','Atlas Cultural Tours','tour',3,'verified',ARRAY['en','fr','de'],'Mid-size cultural tour operator with air-conditioned minibuses and university-trained historians. We cover major landmarks with comfortable logistics.',1,89.6,449,3.9,'active'),
('bd0b2002-25d1-4d3f-a28a-15905f3750e8','MA','a07070a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Concierge Dades Valley SARL','Royal Concierge Dades Valley','tour',4,'verified',ARRAY['en','fr','es','it'],'Private luxury touring service with Mercedes vans, art-historian guides, and exclusive access to private palaces and collections not open to the public.',4.6,88.5,378,4.2,'active'),
